	situ_out[situ_at] = (uint8_t)type;
	situ_at += 1u;

	if (situ_cap - situ_at < 1u) {
		return SITU_ERR_BOUNDS;
	}
	situ_out[situ_at] = (uint8_t)kind;
	situ_at += 1u;

	if (situ_cap - situ_at < 4u) {
		return SITU_ERR_BOUNDS;
	}
	situ_put_be32(situ_out + situ_at,
	              (uint32_t)total);
	situ_at += 4u;

	if (situ_cap - situ_at < 4u) {
		return SITU_ERR_BOUNDS;
	}
	situ_put_be32(situ_out + situ_at,
	              (uint32_t)from);
